<script setup lang="ts">
import { computed, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { SDateTimeInput, SField, SForm, SFormModal, SInput, toast, type Rules } from '@sub2api/ui'
import { useModalForm } from '@/composables/useModalForm'
import { topupApi } from '../api'
import type { PromoCode, PromoInput } from '../topup'

// Creates a promo code (an empty code is generated by the server) or edits
// one; the code itself is fixed once created (users may hold it already).
const props = defineProps<{ open: boolean; promo: PromoCode | null }>()
const emit = defineEmits<{ 'update:open': [open: boolean]; saved: [] }>()
const { t } = useI18n()

interface Draft extends Record<string, unknown> {
  code?: string
  bonus_amount?: number
  min_amount?: number
  max_uses?: number
  expires_at?: string
  notes?: string
}

const editing = computed(() => !!props.promo)
// A new expiry must lie ahead; one kept as it was may have passed (the code shows as expired).
const future = (v: unknown) => !v || v === props.promo?.expires_at || Date.parse(String(v)) > Date.now() || t('topup.admin.futureTime')
const rules: Rules<Draft> = {
  code: { pattern: /^[A-Za-z0-9_-]{3,64}$/, message: () => t('topup.admin.promo.form.codeInvalid') },
  bonus_amount: [{ required: true, type: 'number' }, { validator: v => Number(v) > 0 || t('topup.admin.positive') }],
  min_amount: { required: true, type: 'number', min: 0 },
  max_uses: { required: true, type: 'integer', min: 0 },
  expires_at: { validator: future },
  notes: { max: 200 }
}

const fromPromo = (p: PromoCode | null): Draft =>
  p
    ? {
        code: p.code,
        bonus_amount: Number(p.bonus_amount),
        min_amount: Number(p.min_amount),
        max_uses: p.max_uses,
        expires_at: p.expires_at,
        notes: p.notes
      }
    : { bonus_amount: 5, min_amount: 20, max_uses: 0 }
const { form, saving, reset, submit } = useModalForm<Draft>(() => fromPromo(props.promo), rules)
watch(
  () => props.open,
  open => open && reset()
)

/** The request body: amounts as decimal strings, trimmed text, no code when editing or left empty. */
function body(d: Draft): PromoInput {
  const code = editing.value ? undefined : d.code?.trim().toUpperCase() || undefined
  // An emptied expiry is sent as null so an edit can take it away.
  return {
    code,
    bonus_amount: String(d.bonus_amount),
    min_amount: String(d.min_amount),
    max_uses: Number(d.max_uses),
    expires_at: d.expires_at || null,
    notes: d.notes?.trim() ?? ''
  }
}

async function save() {
  const p = props.promo
  const ok = await submit(d => (p ? topupApi.updatePromoCode(p.id, body(d)) : topupApi.createPromoCode(body(d))))
  if (!ok) return
  toast(t('topup.admin.promo.saved'), 'success')
  emit('update:open', false)
  emit('saved')
}
</script>

<template>
  <SFormModal
    :open="open"
    :title="editing ? t('topup.admin.promo.form.editTitle', { code: promo?.code }) : t('topup.admin.promo.form.createTitle')"
    :loading="saving"
    @update:open="emit('update:open', $event)"
    @submit="save"
  >
    <SForm :form="form">
      <SField
        prop="code"
        :label="t('topup.admin.promo.form.code')"
        :hint="editing ? t('topup.admin.promo.form.codeFixed') : t('topup.admin.promo.form.codeHint')"
      >
        <SInput mono :disabled="editing" :placeholder="t('topup.admin.promo.form.codePlaceholder')" v-bind="form.bind('code')" />
      </SField>
      <SField prop="bonus_amount" :label="t('topup.admin.promo.form.bonus')" :hint="t('topup.admin.promo.form.bonusHint')">
        <SInput type="number" min="0" step="0.01" suffix="USD" v-bind="form.bindNumber('bonus_amount')" />
      </SField>
      <SField prop="min_amount" :label="t('topup.admin.promo.form.minAmount')" :hint="t('topup.admin.promo.form.minAmountHint')">
        <SInput type="number" min="0" step="1" suffix="USD" v-bind="form.bindNumber('min_amount')" />
      </SField>
      <SField prop="max_uses" :label="t('topup.admin.promo.form.maxUses')" :hint="t('topup.admin.promo.form.maxUsesHint')">
        <SInput type="number" min="0" step="1" v-bind="form.bindNumber('max_uses')" />
      </SField>
      <SField prop="expires_at" :label="t('topup.admin.promo.form.expires')" :hint="t('topup.admin.promo.form.expiresHint')">
        <SDateTimeInput v-bind="form.bind('expires_at')" />
      </SField>
      <SField prop="notes" :label="t('topup.admin.promo.form.notes')">
        <SInput v-bind="form.bind('notes')" />
      </SField>
    </SForm>
  </SFormModal>
</template>
